package com.rpb.reservation.workforce;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import static org.assertj.core.api.Assertions.*;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class WorkforcePayPlanEstimatePostgresTest extends WorkforcePayrollPostgresTest {
 PayPlanEstimateService estimator(){return new PayPlanEstimateService(new PayrollAccess(access,directory,jdbc),configs,repository,new PayrollCalculationService(time));}
 PayPlanEstimateDtos.Request request(String basis){var p=configs.findProfile(tenant,profile).orElseThrow();return new PayPlanEstimateDtos.Request(company,employee,"2026-10",new Rule(basis,basis.equals("monthly")?"3000":"15","8","44",false,"1.5",List.of(new Item("职务津贴","ow_allowance","200","full"),new Item("现金住宿","ow_accommodation","300","full"),new Item("全勤奖","ow_attendance","100","full"))),p.cpf(),new CdacProfile("not_applicable",""),22,"8");}
 @Test void fullMonthWithAllowancesUsesExistingRulesAndNeverCreatesPayroll(){var r=estimator().estimate(admin,store,request("monthly"));assertThat(r.breakdown().gross()).isEqualTo("3600.00");assertThat(r.policy()).contains(" / v1").doesNotContain(configs.activePolicy(tenant,YearMonth.of(2026,10)).id().toString());assertThat(r.breakdown().net()).isEqualTo("2880.00");assertThat(r.breakdown().accommodation()).isEqualTo("300.00");assertThat(r.breakdown().allowance()).isEqualTo("300.00");assertThat(r.breakdown().items()).anyMatch(i->i.label().equals("全勤奖")&&i.amount().equals("100.00"));assertThat(payRepository.list(tenant,company,LocalDate.of(2026,1,1))).isEmpty();}
 @Test void hourlyAndDailyAreExplicitFullAttendanceUnits(){assertThat(estimator().estimate(admin,store,request("hourly")).breakdown().gross()).isEqualTo("3240.00");assertThat(estimator().estimate(admin,store,request("daily")).breakdown().gross()).isEqualTo("930.00");}
 @Test void fixedMonthlyBonusReadsApprovedEligibilitySources(){
  var prior=configs.findProfile(tenant,profile).orElseThrow();var fixedRule=new Rule("monthly","3000","8","44",false,"1.5",List.of(new Item("Full attendance","ow_attendance","100","full")),new Generation("fixed",List.of()));legacyProfile(new PayProfile(prior.id(),company,employee,prior.employeeName(),prior.effectiveFrom(),prior.templateId(),prior.templateVersion(),fixedRule,prior.cpf(),prior.version()+1));
  var rules=new com.rpb.reservation.workforce.scheduling.rules.AttendanceRules(1,List.of(),0,0,0,"full",List.of(new com.rpb.reservation.workforce.scheduling.rules.AttendanceRules.AnomalyRule("LATE","Late",true,true)),null,null);
  var shift=shifts.save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.scheduling.SchedulingDtos.ShiftWrite(0L,"Reviewed bonus shift","09:00","17:00",false,"none",0,0,0,0,false,true,rules));
  var work=roster.save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.scheduling.SchedulingDtos.ScheduleWrite(0L,employee,shift.id(),LocalDate.of(2026,10,28),"scheduled"));attendance.save(tenant,new com.rpb.reservation.workforce.attendance.AttendanceDtos.Session(UUID.randomUUID(),work.id(),employee,store,work.startAt(),work.endAt(),null,List.of(),false,1));time.at("2026-11-02T01:00:00Z");var row=approvals.detail(admin,store,work.id()).row();approvals.approve(admin,store,work.id(),new com.rpb.reservation.workforce.approval.ApprovalDtos.ApprovalWrite(0L,row.sourceFingerprint(),"Reviewed attendance eligibility"));
  var capture=sources.capture(tenant,company,YearMonth.of(2026,10),List.of());assertThat(capture.lines().getFirst().sources()).hasSize(1);assertThat(capture.lines().getFirst().attendanceBonusStatus()).isEqualTo("eligible");var result=new PayrollCalculationService(time).calculate(capture,YearMonth.of(2026,10));assertThat(result.issues()).isEmpty();assertThat(result.totalGross()).isEqualTo("3100.00");
 }

 @Test void actualBonusUsesEligibilityAndNeverChangesConfiguredAmount(){
  completed();var base=sources.capture(tenant,company,YearMonth.of(2026,10),List.of());var original=base.lines().getFirst();var p=original.profile();var r=p.rule();var rule=new Rule(r.basis(),r.rate(),r.dayHours(),r.weekHours(),r.overtimeEnabled(),r.overtimeMultiplier(),List.of(new Item("Full attendance","ow_attendance","100","full")));
  var profileWithBonus=new PayProfile(p.id(),p.companyId(),p.employeeId(),p.employeeName(),p.effectiveFrom(),p.templateId(),p.templateVersion(),rule,p.cpf(),p.version(),p.payment(),p.cdac());
  for(var status:List.of("eligible","ineligible","pending","deferred")){var line=new PayrollSources.CapturedLine(original.employee(),profileWithBonus,original.input(),original.sources(),original.issues(),false,original.governance(),null,status);var result=new PayrollCalculationService(time).calculate(new PayrollSources.Capture(base.fingerprint(),base.company(),List.of(line),base.stores(),base.statutoryPolicy()),YearMonth.of(2026,10));assertThat(result.lines().getFirst().grossPay()).isEqualTo(status.equals("eligible")?"900.00":"800.00");assertThat(result.issues().contains("ATTENDANCE_BONUS_REVIEW_REQUIRED")).isEqualTo(status.equals("pending"));assertThat(result.lines().getFirst().profile().rule().items().getFirst().amount()).isEqualTo("100");}
 }
 @Test void estimateKeepsPayrollScopeAndMissingPolicyUnknown(){assertThatThrownBy(()->estimator().estimate(worker,store,request("monthly"))).isInstanceOf(WorkforceException.class);jdbc.update("update workforce_statutory_policies set enabled=false where tenant_id=?",tenant);assertThatThrownBy(()->estimator().estimate(admin,store,request("monthly"))).isInstanceOf(WorkforceException.class);}
}
